// Synthetic DOM only: no account, credential, network service or live grant.
const shell=script=>`<!doctype html><meta charset="utf-8"><body><main id="app"></main><script>window.syntheticFinalGrants=0;${script}</script>`;
export const pages={
 tunnels:shell(`app.innerHTML='<button id="add">Create tunnel</button><table><tbody id="rows"></tbody></table>';add.onclick=()=>{app.insertAdjacentHTML('beforeend','<div role="dialog"><input placeholder="e.g. West Coast MCP tunnel"><textarea placeholder="Add a short description to help your team."></textarea><input placeholder="Search workspaces by name or ID"><button id="create">Create</button></div>');create.onclick=()=>{window.syntheticFinalGrants++;const d=document.querySelector('[role=dialog]'),name=d.querySelector('input').value;rows.innerHTML='<tr><td>'+name+'</td><td>tunnel_1234567890abcdef1234567890abcdef</td><td>org-synthetic</td><td>12345678-1234-1234-1234-123456789abc</td></tr>';d.remove();};};`),
 keys:shell(`app.innerHTML='<button id="add">Create new secret key</button><section role="region" aria-label="API keys"><div class="api-keys-filter-chips"><button>Add filter</button></div><span>0 results</span><table><thead><tr><th>Name</th><th>Permissions</th></tr></thead><tbody id="keyrows"></tbody></table></section>';add.onclick=()=>{app.insertAdjacentHTML('beforeend','<div role="dialog"><input placeholder="My Test Key"><label><input type="radio" name="permissions" value="all">All</label><label><input type="radio" name="permissions" value="restricted" id="restricted">Restricted</label><button id="project">Select project...</button><span role="button" id="expiry">有效期 选择有效期</span><input id="project-key-expiration" aria-hidden="true" type="hidden" value=""><div id="grid"></div><div id="selectedCount"></div><button id="create">Create secret key</button></div>');restricted.onchange=()=>{grid.innerHTML='<div><button disabled><span>Tunnels</span></button><span role="button" aria-haspopup="dialog" id="tunnels"><span>None</span></span></div><div><button disabled><span>Models</span></button><span role="button" aria-haspopup="dialog"><span>None</span></span></div>';tunnels.onclick=()=>{app.insertAdjacentHTML('beforeend','<div role="listbox" aria-multiselectable="true" id="list"><div role="option" data-option-id="api.organization.tunnel.read" aria-selected="false">Read</div><div role="option" data-option-id="api.organization.tunnel.use" aria-selected="false">Use</div></div>');list.onclick=e=>{if(e.target.matches('[role=option]')){e.target.setAttribute('aria-selected','true');const n=list.querySelectorAll('[aria-selected=true]').length;tunnels.textContent=n===2?'All selected':n+' selected';selectedCount.textContent=n+' selected permissions';}};};};project.onclick=()=>{app.insertAdjacentHTML('beforeend','<div role="option" id="defaultProject">Default project</div>');defaultProject.onclick=()=>{project.textContent='Default project';defaultProject.remove();};};expiry.onclick=()=>{app.insertAdjacentHTML('beforeend','<div role="option" id="thirty">30天</div>');thirty.onclick=()=>{expiry.textContent='有效期 30天';document.getElementById('project-key-expiration').value='30';thirty.remove();};};create.onclick=()=>{window.syntheticFinalGrants++;document.querySelector('[role=dialog]').innerHTML='<h2>Save your key</h2><input readonly value="sk-synthetic_runtime_key_abcdefghijklmnopqrstuvwxyz">';};};document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('[role=listbox]')?.remove();});`),
 plugins:shell(`app.innerHTML='<button id="add">添加</button><input placeholder="搜索插件"><nav aria-label="自定义"><div class="group/nav-section"><div>已安装</div><div class="group/nav-list" id="items"></div></div></nav>';const installed=()=>{const name=localStorage.getItem('syntheticPluginName');if(name)items.innerHTML='<a href="/plugins/plugin_asdk_app_synthetic12345678">'+name+'</a>';};installed();add.onclick=()=>{app.insertAdjacentHTML('beforeend','<button role="menuitem" id="custom">添加自定义 MCP 服务器</button>');custom.onclick=()=>{custom.remove();app.insertAdjacentHTML('beforeend','<div role="dialog"><input placeholder="自定义工具"><textarea placeholder="用几句话说明它的功能"></textarea><button id="tunnel">隧道</button><div id="connection"></div><select><option value="OAUTH">OAuth</option><option value="NONE">无需身份验证</option><option value="MIXED">OAuth 或无需身份验证</option></select><label><input type="checkbox" id="risk">我已了解，并希望继续</label><button id="create">创建为插件</button></div>');tunnel.onclick=()=>connection.innerHTML='<input placeholder="tunnel_...">';create.onclick=()=>{window.syntheticFinalGrants++;if(!risk.checked)return;const d=document.querySelector('[role=dialog]'),name=d.querySelector('input').value;localStorage.setItem('syntheticPluginName',name);d.remove();installed();};};};`),
 pluginDetail:shell(`const h=document.createElement('h1');h.textContent=localStorage.getItem('syntheticPluginName');app.append(h);app.insertAdjacentHTML('beforeend','<a href="/settings/plugins-settings/plugin_asdk_app_synthetic12345678">管理</a><button>在聊天中试用</button>');`),
 pluginSettings:shell(`const h=document.createElement('h1');h.textContent=localStorage.getItem('syntheticPluginName');app.append(h);app.insertAdjacentHTML('beforeend','<button>卸载</button><div><span>关联日期</span><span>2026年10月22日</span></div><p>支持授权 无</p><p>使用授权 无</p>');`),
 dot:shell(`app.innerHTML='<div role="textbox" aria-label="消息" contenteditable="true"></div><button aria-label="发送" id="send">发送</button><div id="sent"></div>';send.onclick=()=>{const editor=document.querySelector('[role=textbox]');const item=document.createElement('p');item.setAttribute('data-synthetic-message','true');item.textContent=editor.textContent;sent.append(item);editor.textContent='';};`),
 changed:shell(`app.innerHTML='<p>Unknown replacement page</p>';`),
};
